function build(){
  var st=D.createElement('style');st.textContent=CSS;D.head.appendChild(st);
  var pl=D.createElement('div');pl.id='sc-plane';pl.innerHTML=PLANE;D.body.appendChild(pl);
  var stage=D.createElement('button');stage.id='sc-stage';stage.type='button';stage.setAttribute('aria-label','Chat with Scout, the Search Converts guide');stage.innerHTML=SVG;D.body.appendChild(stage);
  var bub=D.createElement('div');bub.id='sc-bub';bub.setAttribute('role','status');D.body.appendChild(bub);
  var x=D.createElement('button');x.id='sc-x';x.type='button';x.setAttribute('aria-label','Close Scout');x.textContent='\u00d7';D.body.appendChild(x);
  var peek=D.createElement('button');peek.id='sc-peek';peek.type='button';peek.setAttribute('aria-label','Open Scout');peek.innerHTML=HEAD+'<i class="hnd"></i>';D.body.appendChild(peek);
  var panel=D.createElement('div');panel.id='sc-panel';panel.setAttribute('role','dialog');panel.setAttribute('aria-label','Scout chat');panel.innerHTML='<div class="hd">'+HEAD+'<div><b>Scout</b><small>Search Converts guide \u00b7 scripted, not a person</small></div><button type="button" id="sc-pclose" aria-label="Close chat">\u00d7</button></div><div id="sc-log" aria-live="polite"></div><div id="sc-qs">'+CHIPS.map(function(c){return '<button type="button" data-q="'+c+'">'+c+'</button>';}).join('')+'</div><form id="sc-form" autocomplete="off"><input id="sc-in" type="text" placeholder="Ask Scout anything\u2026" aria-label="Ask Scout" maxlength="300"><button type="submit">Ask</button></form>';D.body.appendChild(panel);
  return {pl:pl,stage:stage,bub:bub,x:x,peek:peek,panel:panel};
}
