try{said=JSON.parse(sessionStorage.getItem('scSaid')||'{}');}catch(e){}
function pick(list){var k=list.filter(function(s){return !said[s.slice(0,30)];});if(!k.length){k=list;}var s=k[Math.floor(Math.random()*k.length)];said[s.slice(0,30)]=1;try{sessionStorage.setItem('scSaid',JSON.stringify(said));}catch(e){}return s;}
function opener(){var p=location.pathname;var list=OPEN[p]||OPEN['default'];return pick(list.concat(OPEN['default']).filter(function(v,i,a){return a.indexOf(v)===i;}));}
