var last=null,jokeIdx=-1;
function norm(q){var t=' '+q.toLowerCase().replace(/[^a-z0-9#@'\/\s-]/g,' ').replace(/\s+/g,' ').trim()+' ';NORM.forEach(function(n){t=t.replace(n[0],n[1]);});return ' '+t.replace(/\s+/g,' ').trim()+' ';}
function hit(t,k){var a=k.toLowerCase(),b=a.replace(/'/g,'');return t.indexOf(' '+a+' ')>-1||t.indexOf(' '+b+' ')>-1||t.indexOf(' '+b+'s ')>-1||t.indexOf(' '+b+'es ')>-1;}
function answer(q){say(W.SC?W.SC.esc(q):q,'u');var t=norm(q),best=null,bs=0,words=t.trim().split(' ').length;
  KB.forEach(function(k){var sc=0;k[0].forEach(function(w){if(hit(t,w)){var v=w.length*(w.indexOf(' ')>-1?1.6:1);if(t.trim()===w)v+=12;if(v>sc)sc=v;}});sc*=(k[2]||1);if(sc>bs){bs=sc;best=k;}});
  var out;
  if(best&&best[1][0]==='__JOKE__'){ if(last==='joke'||/joke/.test(t)){best=KB.filter(function(k){return k[0][0]==='joke';})[0];} else {best=KB.filter(function(k){return k[0][0]==='cool';})[0];} }
  if(best&&best[1][0]==='__YES__'){out=last==='joke'?null:(last&&FOLLOW[last])||"Great. The easiest next step is a quick call: <a href=\""+TELH+"\">"+TEL+"</a>, or the <a href=\"/contact/\">contact form</a> and a person calls you. Which works?";if(out===null)best=KB.filter(function(k){return k[0][0]==='joke';})[0];}
  if(!out){ if(best){out=pick(best[1]);last=best[0][0];} else {out=pick(FALLBACK);last=null;} }
  if(best&&best[1]&&best[1][0]!=='__YES__')last=best[0][0];
  var wait=Math.min(900,280+out.length*2);setTimeout(function(){say(out,'b');},wait);}
var FOLLOW={'price':"Great. Tell me what you sell and roughly what one customer is worth, and a strategist can give you a real range. Fastest: <a href=\""+TELH+"\">"+TEL+"</a>.",'audit':"Perfect. Head to the <a href=\"/cro-audit/\">free conversion audit</a> and send your site. A real person reviews it.",'traffic but no calls':"Good call. Start with the <a href=\"/cro-audit/\">free audit</a>, or call <a href=\""+TELH+"\">"+TEL+"</a> and we'll look at it together.",'seo or ads':"Nice. A 15-minute call sorts out the right mix for your market: <a href=\""+TELH+"\">"+TEL+"</a>.",'idk':"Easy start: take the <a href=\"/cro-audit/\">free audit</a> self-check. It takes about two minutes."};
